type Settings={language:'zh-CN';theme:'system'|'light'|'dark';start_page:'home'|'recent';onboarding_complete:boolean};
type Meta={name:string;player_a:string;player_b:string;date:string;event:string;notes:string;synthetic:boolean};
type Issue={level:string;row:number|null;field:string;message:string};
type Match={id:string;metadata:Meta;points:Record<string,string>[];validation:{valid:boolean;issues:Issue[];row_count:number};analysis:any;provenance:any};
const planned:Record<string,string>={player:'长期球员趋势',training:'训练分析',coach:'AI 教练'};
const plannedText:Record<string,string>={player:'未来汇总长期比赛历史与个人趋势；当前可查看运动员基础资料和已登记比赛。',training:'未来整理训练记录、负荷与状态趋势。',video:'未来关联视频时间轴与逐分记录。',coach:'未来基于结构化证据提供辅助分析；当前没有 AI 对话或外部模型调用。'};
const fieldNames:Record<string,string>={game:'局',game_number:'局',point:'本局第几分',point_number:'本局第几分',server:'发球方',receiver:'接发方',winner:'得分方',point_winner:'得分方',score_a:'A 比分',score_b:'B 比分',rally_length:'回合长度（触球次数）',third_ball_attack:'第三板抢攻',serve_placement:'发球落点',serve_type:'发球旋转',serve_spin:'发球旋转',serve_length:'发球长短',serve_location:'发球位置',receive_type:'接发方式',point_phase:'得分阶段',outcome:'结束方式',csv:'CSV 文件',header:'表头',perspective:'球员对应关系',score_before:'本分开始前比分',match_id:'比赛标识',notes:'证据备注',video_timestamp:'视频时间',serve_side:'发球侧',receive_location:'接发落点',third_ball_side:'第三板抢攻侧',third_ball_outcome:'第三板即时结果',point_outcome:'得分结果',server_score_before:'发球方开始前比分',receiver_score_before:'接发方开始前比分'};
const values:Record<string,string>={unknown:'未知',unclear:'无法判断',not_applicable:'不适用',yes:'是',no:'否',short:'短球',half_long:'半出台',long:'长球',forehand:'正手',backhand:'反手',middle:'中路',backspin:'下旋',topspin:'上旋',sidespin:'侧旋',no_spin:'不转',mixed:'混合旋转',push:'搓球',flick:'挑打',chiquita:'拧拉',drive:'攻球',loop:'弧圈',long_push:'长搓',short_touch:'摆短',attack:'进攻',block:'挡球',other:'其他',short_fh:'短球·正手',short_bh:'短球·反手',short_middle:'短球·中路',long_fh:'长球·正手',long_bh:'长球·反手',long_middle:'长球·中路',serve:'发球',receive:'接发',third_ball:'第三板',rally:'相持',winner:'主动得分',error:'失误',win:'赢分',loss:'丢分',successful:'成功',unsuccessful:'未成功'};
const metricNames:Record<string,string>={points_won:'得分率',serve_win:'发球得分率',receive_win:'接发得分率',third_ball_attack:'第三板抢攻率',third_ball_win:'第三板抢攻得分率',average_rally:'平均回合长度'};
const metricHelp:Record<string,string>={points_won:'赢下的分 / 全部有效分。',serve_win:'Serve Win % · 发球时赢下的分 / 发球分。',receive_win:'Receive Win % · 接发时赢下的分 / 接发分。',third_ball_attack:'Third-ball Attack Rate · 已确认抢攻 / 已标注是或否的发球机会。',third_ball_win:'已确认抢攻后赢下该分 / 已确认抢攻机会；不代表第三板直接得分。',average_rally:'Average Rally Length · 包含发球在内的平均触球次数。'};
