async function api(path:string,options?:RequestInit){const r=await fetch('/api'+path,options);if(!r.ok){const detail=await r.text();throw new Error(r.status+' '+detail)}return r.json()}
function schemaName(s:string){return s==='protocol_v0_3'?'研究格式 · Protocol v0.3':s==='1.0.0-new'?'PTTI 标准格式':'旧版保存结果'}
function countryName(code:string|null){return ({CHN:'中国',JPN:'日本',TPE:'中华台北',FRA:'法国',SWE:'瑞典',BRA:'巴西',GER:'德国',DEN:'丹麦'} as Record<string,string>)[code||'']||code||'协会待核实'}
function competitionName(code:string|null){return ({WTT_GRAND_SMASH:'WTT 大满贯',WTT_STAR_CONTENDER:'WTT 挑战赛',ITTF_WORLD_CUP:'国际乒联世界杯',WTT_CHAMPIONS:'WTT 冠军赛',WTT_FINALS:'WTT 总决赛'} as Record<string,string>)[code||'']||code||'职业比赛'}
function roundName(value:string|null){return ({"Men's Singles Final":'男子单打决赛',"Men's Singles Semifinal":'男子单打半决赛',"Men's Singles Round of 64":'男子单打 64 强'} as Record<string,string>)[value||'']||value||'轮次未核实'}
function rankingTypeName(value:string){return value==='ITTF_MENS_SINGLES'?'ITTF 男子单打':value}
function display(value:string){return values[value]||value||'—'}
function fieldLabel(field:string){return field.split('/').map(f=>fieldNames[f.replace('source_','')]||f).join(' / ')}
function issueText(i:Issue){const mapped=i.message.match(/^接发类别 (\w+) 合并为 (\w+)；/);if(mapped)return '接发记录“'+display(mapped[1])+'”按产品分类合并为“'+display(mapped[2])+'”。原始细分类别仍完整保留。';if(i.message==='Use a valid UTF-8 CSV.')return '文件编码或格式无法读取，请另存为 UTF-8 CSV。';return i.message.replace(/缺少可选字段 (\w+)/,(_,f)=>'缺少可选字段“'+fieldLabel(f)+'”')}
function suggestion(i:Issue){if(i.level==='error')return /比分|score/.test(i.field+i.message)?'对照逐分记录修正比分与得分方；不要补猜。':'检查所示行和字段，按模板修正后重新选择文件。';return '可继续保存；相关统计只使用已确认记录，原始值不会被猜测补齐。'}
function Issues({items}:{items:Issue[]}){return <div className="issues">{items.length===0?<p className="success">✓ 数据检查通过，没有错误或警告。</p>:items.map((i,n)=><article className={'issue '+i.level} key={n}><div><span className="badge">{i.level==='error'?'× 错误 · 必须修复':i.level==='warning'?'! 警告 · 可以继续':'ⓘ 提示'}</span><strong>{i.row?'第 '+i.row+' 行':'整场数据'} · {fieldLabel(i.field)}</strong></div><p>{issueText(i)}</p><small>建议：{suggestion(i)}</small></article>)}</div>}

function WTTInbox({athletes,onImported}:{athletes:any[];onImported:()=>void}){
 const [items,setItems]=useState<any[]>([]),[directory,setDirectory]=useState(''),[selected,setSelected]=useState<any>(null);
 const [file,setFile]=useState<File|null>(null),[eventName,setEventName]=useState(''),[round,setRound]=useState(''),[sourceUrl,setSourceUrl]=useState('');
 const [assetId,setAssetId]=useState(''),[licence,setLicence]=useState(''),[note,setNote]=useState(''),[a,setA]=useState(''),[b,setB]=useState('');
 const [rights,setRights]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState('');
 async function scan(){try{const value=await api('/professional-matches/inbox');setItems(value.items||[]);setDirectory(value.inbox_directory||'')}catch(e){setError(String(e))}}
 useEffect(()=>{scan();const timer=setInterval(scan,30000);return()=>clearInterval(timer)},[]);
 function selectItem(item:any){setSelected(item);setFile(null);if(item.candidate_athlete_ids?.length===2){setA(item.candidate_athlete_ids[0]);setB(item.candidate_athlete_ids[1])}}
 async function inspectSelectedFile(){if(!file)return;setBusy(true);setError('');try{const data=new FormData();data.append('file',file);data.append('rights_confirmed',String(rights));data.append('video_source_note',note);const item=await api('/professional-matches/inbox/stage',{method:'POST',body:data});setItems((current:any[])=>[item,...current.filter(x=>x.sha256!==item.sha256)]);setSelected(item);setFile(null);if(item.candidate_athlete_ids?.length===2){setA(item.candidate_athlete_ids[0]);setB(item.candidate_athlete_ids[1])}}catch(e){setError(String(e))}finally{setBusy(false)}}
 async function importVideo(){if(!selected&&!file)return;setBusy(true);setError('');try{const data=new FormData();data.append('metadata',JSON.stringify({event_name:eventName,round:round||null,player_a_id:a,player_b_id:b,external_reference_url:sourceUrl,video_source_type:'LICENSED_WTT_LOCAL',rights_status:'LICENSED_FOR_ANALYSIS',wtt_asset_id:assetId,licence_reference:licence,original_filename:selected?.original_filename||selected?.filename||file?.name}));data.append('rights_confirmed',String(rights));data.append('video_source_note',note);if(file)data.append('file',file);else data.append('inbox_id',selected.inbox_id);await api('/professional-matches/inbox/import',{method:'POST',body:data});setSelected(null);setFile(null);setRights(false);setEventName('');setRound('');setSourceUrl('');setAssetId('');setLicence('');setNote('');await scan();onImported()}catch(e){setError(String(e))}finally{setBusy(false)}}
 return <><PageHeader title="WTT 授权视频入口" text="请先在 WTT Media Archive 网站完成登录、许可与下载。PTTI 只读取你明确放入入口或通过文件选择的本机视频。"/>
  <Card><h2>本机收件目录</h2><p>把通过官方流程获得许可的视频放入此文件夹，或明确选择下载目录中的单个文件。这里只检查此专用目录，不扫描其他磁盘。</p><code className="mono">{directory||'正在读取入口路径…'}</code><div className="actions"><button onClick={scan}>重新扫描入口</button><label className="file-button">选择本机视频<input type="file" accept=".mp4,.mov,.mkv,.avi,video/mp4,video/quicktime,video/x-matroska,video/x-msvideo" onChange={e=>{setFile(e.target.files?.[0]||null);setSelected(null)}}/></label></div>{file&&<><p>已选择：{file.name} · {(file.size/1024/1024).toFixed(1)} MB。完成授权核对后，先读取视频属性再登记。</p><label>授权与来源说明<input value={note} onChange={e=>setNote(e.target.value)} placeholder="说明如何通过官方流程获得许可"/></label><label className="check"><input type="checkbox" checked={rights} onChange={e=>setRights(e.target.checked)}/> 我确认该文件允许本机分析</label><button disabled={busy||!rights||!note.trim()} onClick={inspectSelectedFile}>读取视频属性并继续</button></>}</Card>
  <div className="library-grid">{items.map((item:any)=><Card key={item.inbox_id||item.filename}><div className="card-top"><span className="badge">{item.duplicate?'重复文件':item.error?'无法读取':'需要人工核对'}</span></div><h3>{item.filename}</h3>{item.error?<p role="alert">{item.error}</p>:<><p>SHA-256：<span className="mono">{item.sha256}</span></p><p>{item.video?.duration?.toFixed(1)} 秒 · {item.video?.width}×{item.video?.height} · {item.video?.fps} FPS · {item.video?.codec} · {(item.size_bytes/1024/1024).toFixed(1)} MB</p><p>可能涉及的运动员：{item.candidate_athlete_ids?.map((id:string)=>athletes.find(x=>x.athlete_id===id)?.canonical_name_zh||id).join('、')||'未能从文件名识别；请手动选择'}</p><button disabled={item.duplicate} onClick={()=>selectItem(item)}>{item.duplicate?'已登记':'核对并登记此视频'}</button></>}</Card>)}</div>
  {selected&&<Card><h2>比赛与授权信息核对</h2><p>系统不会仅凭文件名确认比赛或运动员。请核对实际比赛、双方球员、WTT Asset 和许可记录。</p><div className="form-grid"><label>赛事<input value={eventName} onChange={e=>setEventName(e.target.value)}/></label><label>轮次<input value={round} onChange={e=>setRound(e.target.value)}/></label><label>球员 A<select value={a} onChange={e=>setA(e.target.value)}><option value="">选择球员</option>{athletes.map(x=><option key={x.athlete_id} value={x.athlete_id}>{x.canonical_name_zh||x.canonical_name_en} · {x.canonical_name_en}</option>)}</select></label><label>球员 B<select value={b} onChange={e=>setB(e.target.value)}><option value="">选择球员</option>{athletes.map(x=><option key={x.athlete_id} value={x.athlete_id}>{x.canonical_name_zh||x.canonical_name_en} · {x.canonical_name_en}</option>)}</select></label><label>WTT Asset / Record ID<input value={assetId} onChange={e=>setAssetId(e.target.value)}/></label><label>许可编号 / 记录<input value={licence} onChange={e=>setLicence(e.target.value)}/></label><label className="wide">官方赛事或媒体来源 URL<input type="url" value={sourceUrl} onChange={e=>setSourceUrl(e.target.value)}/></label><label className="wide">许可与来源说明<input value={note} onChange={e=>setNote(e.target.value)}/></label></div><label className="check"><input type="checkbox" checked={rights} onChange={e=>setRights(e.target.checked)}/> 我确认该文件由 WTT 官方流程授权下载，许可允许本机分析</label><div className="actions"><button onClick={()=>{setSelected(null);setFile(null)}}>取消</button><button className="primary" disabled={busy||!eventName||!a||!b||a===b||!assetId||!licence||!sourceUrl||!note||!rights} onClick={importVideo}>验证并登记比赛</button></div></Card>}
  {error&&<p className="error-banner" role="alert">{error}</p>}
 </>
}

function FullMatchTimeline({matchId,onBack}:{matchId:string;onBack:()=>void}){
 const video=useRef<HTMLVideoElement>(null);const [timeline,setTimeline]=useState<any>(null),[job,setJob]=useState<any>(null),[quality,setQuality]=useState<any>(null),[error,setError]=useState('');
 const [structure,setStructure]=useState<any>(null),[calibrations,setCalibrations]=useState<any[]>([]),[corners,setCorners]=useState<number[][]>([]),[cornerInput,setCornerInput]=useState(''),[calibrationPreview,setCalibrationPreview]=useState(''),[cameraSegment,setCameraSegment]=useState('whole-video'),[busyStructure,setBusyStructure]=useState(false);
 const [participants,setParticipants]=useState<any[]>([]);
 useEffect(()=>{api('/preview/workspace').then(value=>{const m=value.matches.find((item:any)=>item.match_id===matchId);setParticipants(m?[m.players.player_a,m.players.player_b]:[])}).catch(()=>{})},[matchId]);
 const [start,setStart]=useState<number|null>(null),[end,setEnd]=useState<number|null>(null),[game,setGame]=useState(1),[device,setDevice]=useState('cuda');
 const [scoreA,setScoreA]=useState(''),[scoreB,setScoreB]=useState(''),[scorer,setScorer]=useState(''),[server,setServer]=useState('');
 const refresh=async()=>{const [t,j,q]=await Promise.all([api(`/professional-matches/${encodeURIComponent(matchId)}/timeline`),api(`/vision/professional-matches/${encodeURIComponent(matchId)}/full-match`),api(`/vision/professional-matches/${encodeURIComponent(matchId)}/full-match/quality?device=${device}`)]);setTimeline(t);setJob(j);setQuality(q);setGame(Math.max(1,...(t.games||[]).map((x:any)=>x.game_number)))};
 useEffect(()=>{refresh().catch(e=>setError(String(e)))},[matchId]);
 useEffect(()=>{if(!job||!['RUNNING','QUEUED'].includes(job.status))return;const timer=setInterval(()=>api(`/vision/professional-matches/${encodeURIComponent(matchId)}/full-match`).then(setJob).catch(e=>setError(String(e))),3000);return()=>clearInterval(timer)},[job?.status,matchId]);
 async function act(action:any){try{setError('');const result=await api(`/professional-matches/${encodeURIComponent(matchId)}/timeline/actions?expected_revision=${timeline.revision}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action)});setTimeline(result)}catch(e){setError(String(e))}}
 const now=()=>Math.max(0,Math.round((video.current?.currentTime||0)*1000));
 const points=(timeline?.games||[]).flatMap((g:any)=>g.points.map((p:any)=>({...p,game_number:g.game_number})));
 async function run(resume=false){try{setError('');setJob(await api(`/vision/professional-matches/${encodeURIComponent(matchId)}/full-match?device=${device}&resume=${resume}`,{method:'POST'}))}catch(e){setError(String(e))}}
 async function loadStructure(){try{const [s,c]=await Promise.all([api(`/professional-matches/${encodeURIComponent(matchId)}/match-structure`),api(`/professional-matches/${encodeURIComponent(matchId)}/table-calibrations?camera_segment_id=${encodeURIComponent(cameraSegment)}`)]);setStructure(s);setCalibrations(c)}catch{setStructure(null);setCalibrations([])}}
 async function suggestStructure(){setBusyStructure(true);try{setError('');const result=await api(`/professional-matches/${encodeURIComponent(matchId)}/match-structure/suggest`,{method:'POST'});setStructure(result)}catch(e){setError(String(e))}finally{setBusyStructure(false)}}
 async function reviewRally(item:any,action:string,extra:any={}){try{const result=await api(`/professional-matches/${encodeURIComponent(matchId)}/match-structure/${structure.run_id}/rallies/${item.segment_id}/review`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,...extra})});setStructure(result)}catch(e){setError(String(e))}}
 async function saveCalibration(value=corners){try{const result=await api(`/professional-matches/${encodeURIComponent(matchId)}/table-calibrations`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({camera_segment_id:cameraSegment,width:video.current?.videoWidth,height:video.current?.videoHeight,corners:value})});setCalibrations(current=>[...current,result]);setCorners([]);setCornerInput('')}catch(e){setError(String(e))}}
 function captureCalibrationFrame(){const v=video.current;if(!v||!v.videoWidth||!v.videoHeight||!v.paused){setError('请先播放并暂停在清晰的球台画面，再选择校准帧。');return}const canvas=document.createElement('canvas');canvas.width=v.videoWidth;canvas.height=v.videoHeight;canvas.getContext('2d')?.drawImage(v,0,0);setCalibrationPreview(canvas.toDataURL('image/png'));setCorners([])}
 useEffect(()=>{void loadStructure()},[matchId,cameraSegment]);
 useEffect(()=>{const handler=(event:KeyboardEvent)=>{if(!structure)return;const target=event.target as HTMLElement;if(['INPUT','TEXTAREA','SELECT'].includes(target?.tagName)||target?.isContentEditable)return;const pending=(structure.rallies||[]).filter((r:any)=>r.status==='SUGGESTED');if(!pending.length)return;if(event.code==='Space'){event.preventDefault();if(video.current){video.current.paused?void video.current.play():video.current.pause()}}else if(event.key.toLowerCase()==='a'){void reviewRally(pending[0],'accept')}else if(event.key.toLowerCase()==='r'){void reviewRally(pending[0],'reject')}else if(event.key==='['){void reviewRally(pending[0],'adjust',{start_ms:now()})}else if(event.key===']'){void reviewRally(pending[0],'adjust',{end_ms:now()})}};window.addEventListener('keydown',handler);return()=>window.removeEventListener('keydown',handler)},[structure]);
 return <><PageHeader title="比赛时间轴" text="逐分与回合边界由人工确认；未核实的比分和运动员保持空白。"><button onClick={onBack}>返回比赛目录</button></PageHeader>
  <Card><video ref={video} className="timeline-video" src={`/api/professional-matches/${encodeURIComponent(matchId)}/video`} controls preload="metadata"/><p>通过播放器定位，再标记起点与终点。修改会自动保存到本机；所有时间以整场录像起点为 00:00。</p><div className="actions"><button disabled={!points.length} onClick={()=>{const previous=[...points].reverse().find((p:any)=>p.start_ms<now());if(previous&&video.current)video.current.currentTime=previous.start_ms/1000}}>上一分</button><button disabled={!points.length} onClick={()=>{const next=points.find((p:any)=>p.start_ms>now());if(next&&video.current)video.current.currentTime=next.start_ms/1000}}>下一分</button><button onClick={()=>setStart(now())}>标记当前为边界起点 · {start==null?'—':(start/1000).toFixed(2)+'s'}</button><button onClick={()=>setEnd(now())}>标记当前为边界终点 · {end==null?'—':(end/1000).toFixed(2)+'s'}</button><button disabled={start==null||end==null||end<=start} onClick={()=>act({action:'add_point',game_number:game,start_ms:start,end_ms:end})}>添加逐分记录</button></div><div className="actions"><label>当前局 <select value={game} onChange={e=>setGame(Number(e.target.value))}>{(timeline?.games||[]).map((g:any)=><option key={g.game_number} value={g.game_number}>第 {g.game_number} 局</option>)}</select></label><button onClick={()=>act({action:'add_game',game_number:Math.max(0,...(timeline?.games||[]).map((x:any)=>x.game_number))+1,game_start_ms:now()})}>新建一局</button><button disabled={!timeline?.games?.length} onClick={()=>act({action:'mark_game_end',game_number:game,end_ms:now()})}>标记本局结束</button></div></Card>
  <details><summary>高级：球台与镜头校准</summary><Card><h2>球台人工校准</h2><p>按顺序输入球台四角 [近端左角, 近端右角, 远端右角, 远端左角] 的像素坐标，例如 [[10,20],[300,20],[300,180],[10,180]]。坐标只用于映射到标准 0–1 平面，不代表战术结论；绑定视频 SHA 与镜头区段。</p><label>镜头区段标识<input value={cameraSegment} onChange={e=>setCameraSegment(e.target.value)}/></label><button onClick={captureCalibrationFrame}>从当前暂停帧选取球台四角</button>{calibrationPreview&&<><p>依次点击：近端左角、近端右角、远端右角、远端左角。已选 {corners.length}/4 个点。</p><img src={calibrationPreview} alt="球台校准画面；依次点击四角" style={{maxWidth:'100%',height:'auto',cursor:'crosshair'}} onClick={e=>{if(corners.length>=4)return;const rect=e.currentTarget.getBoundingClientRect();const scaleX=e.currentTarget.naturalWidth/rect.width,scaleY=e.currentTarget.naturalHeight/rect.height;const next=[...corners,[(e.clientX-rect.left)*scaleX,(e.clientY-rect.top)*scaleY]];setCorners(next);setCornerInput(JSON.stringify(next))}}/></>}<label>四角像素坐标（可手工修正）<input value={cornerInput} onChange={e=>setCornerInput(e.target.value)} placeholder="[[x,y],[x,y],[x,y],[x,y]]"/></label><button disabled={corners.length!==4&& !cornerInput.trim()} onClick={()=>{try{void saveCalibration(JSON.parse(cornerInput))}catch(e){setError('请依次选择或输入四组角点坐标')}}}>保存此镜头校准</button>{calibrations.map((c:any)=><p key={c.calibration_id}>校准 {c.status} · {c.camera_segment_id} · 绑定视频 {String(c.video_sha256||'').slice(0,12)}… · X 近端球员左至右，Y 近端至远端</p>)}</Card></details>
  <Card><h2>回合候选审核</h2><p>建议仅供人工审核，不会自动修改比赛时间轴。快捷键：空格播放/暂停，A 接受，R 拒绝，[ 调整起点，] 调整终点。</p><div className="actions"><button disabled={busyStructure||job?.status!=="BALLTRACK_COMPLETE"} onClick={suggestStructure}>{busyStructure?'正在分析…':'生成分球候选'}</button><button disabled={!structure} onClick={()=>window.open(`/api/professional-matches/${encodeURIComponent(matchId)}/full-match/asset/match_structure.json`,'_blank')}>查看 JSON 报告</button></div>{structure&&<><p>建议 {structure.rallies?.length||0} 条 · 已确认 {structure.rallies?.filter((r:any)=>r.status==='CONFIRMED').length||0} 条 · 冲突 {structure.conflicts?.length||0} 条 · 状态：{structure.status}</p><div className="timeline-games">{(structure.rallies||[]).map((r:any,i:number)=><article className="timeline-point" key={r.segment_id}><strong>{(r.start_ms/1000).toFixed(2)}–{(r.end_ms/1000).toFixed(2)} 秒 · {r.status==='CONFIRMED'?'已人工确认':r.status==='REJECTED'?'已拒绝':'待人工审核'}</strong><p>依据：{r.evidence?.map((e:any)=>e.type==='BALL_TRACK_LOST'?`连续丢球 ${e.duration_ms.toFixed(0)} ms`:e.type==='BALL_ACTIVITY_BEFORE_AND_AFTER'?`前后时间窗可见观测 ${e.visible_observations_before}/${e.visible_observations_after}`:e.type).join('；')}</p>{r.status==='SUGGESTED'&&<div className="actions"><button onClick={()=>reviewRally(r,'accept')}>接受</button><button onClick={()=>reviewRally(r,'reject')}>拒绝</button><button onClick={()=>reviewRally(r,'adjust',{start_ms:now()})}>当前时间设为起点</button><button onClick={()=>reviewRally(r,'adjust',{end_ms:now()})}>当前时间设为终点</button><button onClick={()=>reviewRally(r,'split',{split_at_ms:Math.floor((r.start_ms+r.end_ms)/2)})}>在中点拆分</button>{structure.rallies[i+1]?.status==='SUGGESTED'&&<button onClick={()=>reviewRally(r,'merge',{target_segment_id:structure.rallies[i+1].segment_id})}>与下一建议合并</button>}</div>}</article>)}</div><p className="small">候选仅依赖全局时间轴上的丢球区间及其前后可见观测。真实标注准确率：暂无数据。确认候选保存在审核记录中，不会自动写入人工逐分/回合结构。</p></>}</Card>
  <Card><h2>整场 BallTrack</h2><p>{job?.stage||'尚未开始'}{job?.total_chunks?` · 已完成 ${job.completed_chunks}/${job.total_chunks} 个分块`:''}</p>{quality&&<div className="facts"><span>视频时长<strong>{Math.floor(quality.duration_seconds/60)}分 {Math.round(quality.duration_seconds%60)}秒</strong></span><span>画面<strong>{quality.resolution.width}×{quality.resolution.height} · {quality.fps} FPS</strong></span><span>编码与码率<strong>{quality.codec} · {quality.bitrate?Math.round(quality.bitrate/1000)+' kbps':'未知'}</strong></span><span>处理规模<strong>约 {quality.estimated_frames.toLocaleString()} 帧 · {quality.estimated_chunk_count} 个分块</strong></span></div>}{quality&&!quality.input_file_present&&<p role="alert">本机登记的视频文件当前不可用。</p>}{quality&&!quality.frozen_checkpoint_present&&<p className="warning-note">冻结版 BallTrack 模型运行环境尚未安装，当前不能启动全场处理。</p>}{job?.last_error&&<p role="alert">{job.last_error}</p>}<label>处理设备 <select value={device} onChange={e=>setDevice(e.target.value)}><option value="cuda">NVIDIA GPU</option><option value="cpu">CPU</option></select></label><div className="actions"><button className="primary" disabled={['RUNNING','QUEUED'].includes(job?.status)||!quality?.input_file_present||!quality?.frozen_checkpoint_present} onClick={()=>run(false)}>开始全场处理</button>{job?.status==='PAUSED'&&<button onClick={()=>run(true)}>从失败分块继续</button>}{job?.report_path&&<a href={`/api/professional-matches/${encodeURIComponent(matchId)}/full-match/asset/full_match_report.html`} target="_blank">打开全场摘要报告</a>}{job?.csv_path&&<a href={`/api/professional-matches/${encodeURIComponent(matchId)}/full-match/asset/full_match_balltrack.csv`} download>下载全场 BallTrack CSV</a>}</div><p className="small">固定 60 秒检查点；推理器按帧流式解码，内存占用不随比赛长度累积。未知镜头会保持 UNKNOWN。BallTrack 仅输出球位置观测，不代表分球或战术分析。</p></Card>
  <Card><div className="section-title"><h2>比赛时间轴</h2><button onClick={()=>act({action:'add_game',game_number:Math.max(0,...(timeline?.games||[]).map((x:any)=>x.game_number))+1,game_start_ms:now()})}>添加一局</button></div><div className="timeline-games">{(timeline?.games||[]).map((g:any)=><section key={g.game_number}><h3>第 {g.game_number} 局</h3><button onClick={()=>{if(window.confirm('确定删除这一局及其逐分记录？'))void act({action:'delete_game',game_number:g.game_number})}}>删除本局</button><p>{(g.start_ms/1000).toFixed(2)}s — {g.end_ms==null?'未标记':(g.end_ms/1000).toFixed(2)+'s'} · {g.points.length} 分</p>{g.points.map((p:any)=><article className="timeline-point" key={p.point_id}><button onClick={()=>{if(video.current)video.current.currentTime=p.start_ms/1000}}>第 {p.point_number} 分 · {(p.start_ms/1000).toFixed(2)}–{(p.end_ms/1000).toFixed(2)} 秒 · {p.review_status==='ACCEPTED'?'已确认':p.review_status==='ADJUSTED'?'已人工调整':'待核对'}</button><span>比分 {p.score_after?`${p.score_after.player_a}:${p.score_after.player_b}`:'未记录'} · 得分方 {p.scorer_id||'未知'} · 回合 {p.rallies.length}</span><div className="actions"><button onClick={()=>act({action:'accept',game_number:g.game_number,point_number:p.point_number})}>确认</button><button onClick={()=>act({action:'adjust',game_number:g.game_number,point_number:p.point_number,start_ms:now()})}>调整起点至当前</button><button onClick={()=>act({action:'adjust',game_number:g.game_number,point_number:p.point_number,end_ms:now()})}>调整终点至当前</button><button onClick={()=>act({action:'split',game_number:g.game_number,point_number:p.point_number,split_at_ms:now()})}>在当前时间拆分</button><button onClick={()=>act({action:'merge',game_number:g.game_number,point_number:p.point_number,next_point_number:p.point_number+1})}>与下一分合并</button><button onClick={()=>{if(window.confirm('确定删除这条逐分记录？'))void act({action:'delete_point',game_number:g.game_number,point_number:p.point_number})}}>删除此分</button></div><div className="form-grid compact"><label>分数 A<input type="number" min="0" value={scoreA} onChange={e=>setScoreA(e.target.value)}/></label><label>分数 B<input type="number" min="0" value={scoreB} onChange={e=>setScoreB(e.target.value)}/></label><label>得分方<select value={scorer} onChange={e=>setScorer(e.target.value)}><option value="">未知</option>{participants.map(a=><option key={a.athlete_id} value={a.athlete_id}>{a.canonical_name_zh||a.canonical_name_en}</option>)}</select></label><label>发球方<select value={server} onChange={e=>setServer(e.target.value)}><option value="">未知</option>{participants.map(a=><option key={a.athlete_id} value={a.athlete_id}>{a.canonical_name_zh||a.canonical_name_en}</option>)}</select></label><button disabled={scoreA===''||scoreB===''} onClick={()=>act({action:'set_score',game_number:g.game_number,point_number:p.point_number,score_after:{player_a:Number(scoreA),player_b:Number(scoreB)},note:'Manual scoreboard entry'})}>手动保存比分</button><button onClick={()=>act({action:'set_participants',game_number:g.game_number,point_number:p.point_number,scorer_id:scorer||null,server_id:server||null,receiver_id:null,note:'Manual participant annotation'})}>保存得分方 / 发球方</button></div><p className="small">关联回合：{p.rallies.length?p.rallies.map((r:any)=>`${(r.start_ms/1000).toFixed(2)}–${(r.end_ms/1000).toFixed(2)}s`).join('、'):'未标记'} <button onClick={()=>act({action:'add_rally',game_number:g.game_number,point_number:p.point_number,rally_start_ms:start??p.start_ms,rally_end_ms:end??p.end_ms,note:'Human-marked rally interval'})}>添加回合</button></p></article>)}</section>)}{!timeline?.games?.length&&<p>尚无时间轴。播放视频并添加第一局和逐分记录。</p>}</div></Card>
  <Card><h2>镜头区段</h2><p>镜头分类由人工确认，系统不自动判断。尚未标注的区段保持“未知”。</p><button disabled={start==null||end==null||end<=start} onClick={()=>act({action:'add_scene',start_ms:start,end_ms:end,note:'人工新增，待分类'})}>将当前边界添加为待分类区段</button>{(timeline?.scene_segments||[]).map((s:any)=><div key={s.scene_id} className="timeline-point">{(s.start_ms/1000).toFixed(1)}–{(s.end_ms/1000).toFixed(1)} 秒 · {s.scene_type}<div className="actions">{[['MATCH_PLAY','比赛画面'],['REPLAY','回放'],['CROWD','观众画面'],['TIMEOUT','暂停'],['BREAK','局间休息'],['UNKNOWN','保持未知']].map(([type,label])=><button key={type} onClick={()=>act({action:'label_scene',scene_id:s.scene_id,scene_type:type,note:'Human reviewed scene type'})}>{label}</button>)}</div></div>)}</Card>
  {error&&<p className="error-banner" role="alert">{error}</p>}
 </>
}
function Provenance({match}:{match:Match}){const p=match.provenance||{},q=match.analysis.evidence||{};return <Card><h2>数据来源与可信度</h2><div className="facts"><span>数据格式<strong>{schemaName(p.source_schema)}</strong></span><span>有效数据<strong>{match.points.length} 分</strong></span><span>原始字段<strong>{p.original_points?'已完整保留':'旧版未记录来源'}</strong></span><span>检查警告<strong>{match.validation.issues.filter(i=>i.level==='warning').length} 条</strong></span></div><p>PTTI 不会自动将未知战术信息推断为确定值。数据充足仅表示可以描述该样本，不等于研究结论可靠。</p><div className="table-wrap"><table><thead><tr><th>证据字段</th><th>适用样本</th><th>未知</th><th>无法判断</th><th>不适用</th><th>缺失</th><th>机会未确认</th></tr></thead><tbody>{Object.entries(q).filter(([,v]:any)=>v.unknown||v.unclear||v.missing||v.unresolved_eligibility).map(([f,v]:any)=><tr key={f}><td>{fieldNames[f.replace('source_','')]||f}</td><td>{v.eligible_rows}</td><td>{v.unknown}</td><td>{v.unclear}</td><td>{v.not_applicable}</td><td>{v.missing}</td><td>{v.unresolved_eligibility}</td></tr>)}</tbody></table></div><details><summary>高级来源信息</summary><p>适配器版本：{p.adapter_version||'无需适配'} · 分析版本：{match.analysis.analytics_version||'0.1.0'}</p><p>来源仓库：{p.source_repository||'用户提供'} · 原始协议：{p.source_schema||'旧版结果'}</p><p className="mono">来源修订：{p.source_revision||'未记录'}</p></details></Card>}
function OpenTTDataset(){
 const [data,setData]=useState<any>(null),[error,setError]=useState('');
 useEffect(()=>{api('/vision/research-datasets/extended-openttgames').then(setData).catch(e=>setError(String(e)))},[]);
 return <Card><h2>Extended OpenTTGames · 真实标注评估</h2><p>研究 / 非商业使用 · CC BY-NC-SA 4.0 · 不进入安装包、发布资产或 Git。</p>
  {error?<p role="alert">数据集状态暂不可用：{error}</p>:!data?<p>正在读取本机研究资料…</p>:<>
   <p>固定版本：<span className="mono">{data.revision}</span> · 标注：{data.annotations_status}</p>
   <p>官方 test split：{data.test_split.status}（{data.test_split.videos} 段）；当前只使用 training split。</p>
   <div className="table-wrap"><table><thead><tr><th>训练比赛</th><th>事件标注</th><th>球坐标标注</th><th>视频</th><th>视频大小</th></tr></thead><tbody>{data.training.annotations.map((a:any)=>{const v=data.training.videos.find((x:any)=>x.id===a.id);return <tr key={a.id}><td>{a.id}</td><td>{a.game_events}</td><td>{a.ball_ground_truth}</td><td>{v.status}</td><td>{v.size_bytes==null?'—':`${(v.size_bytes/1e9).toFixed(2)} GB`}</td></tr>})}</tbody></table></div>
   <p className="small">数据保存在 PTTI-Dev 研究目录。原始标签保留；回合边界由发球与结束标注推导，并明确标作 DERIVED。</p>
  </>}</Card>
}
function previewBuildLabel(build:any){const id=build.build_id||build.build_commit?.slice(0,10);if(build.score_navigation_preview||build.dual_source_preview){return `${build.product_name||'PTTI'} v${build.version||'开发预览'} Preview${id?` · ${id}`:''}`}return build.video_first?`比赛库 ${build.version||'开发预览'}`:build.start_page==='videoEvidence'?`视频证据 ${build.version||'预览版'}`:'v0.2 Professional Preview'}
function App(){
 const [feedQuery,setFeedQuery]=useState('');
 const [page,setPage]=useState('home'),[library,setLibrary]=useState<any[]>([]),[match,setMatch]=useState<Match|null>(null),[settings,setSettings]=useState<Settings>(defaults),[ready,setReady]=useState(false),[onboarding,setOnboarding]=useState(false),[busy,setBusy]=useState(false),[error,setError]=useState(''),[errorDetail,setErrorDetail]=useState(''),[toast,setToast]=useState(''),[versions,setVersions]=useState<any>({}),[section,setSection]=useState('overview');
  const [athletes,setAthletes]=useState<any[]>([]),[playerGroups,setPlayerGroups]=useState<any[]>([]),[proMatches,setProMatches]=useState<any[]>([]),[selectedAthlete,setSelectedAthlete]=useState<any>(null),[playerGroupFilter,setPlayerGroupFilter]=useState('CURRENT_ELITE'),[playerSearch,setPlayerSearch]=useState(''),[timelineMatchId,setTimelineMatchId]=useState('');
 const [proDraft,setProDraft]=useState<any>({event_name:'',player_a_id:'',player_b_id:'',round:'',external_reference_url:''}),[proVideo,setProVideo]=useState<File|null>(null),[proRightsConfirmed,setProRightsConfirmed]=useState(false),[proVideoSourceNote,setProVideoSourceNote]=useState('');
 const [meta,setMeta]=useState<Meta>(initialMeta),[file,setFile]=useState<File|null>(null),[step,setStep]=useState(1),[preview,setPreview]=useState<any>(null),[search,setSearch]=useState(''),[date,setDate]=useState(''),[deleteTarget,setDeleteTarget]=useState<any>(null);
 const [pointSearch,setPointSearch]=useState(''),[game,setGame]=useState('all'),[server,setServer]=useState('all'),[winner,setWinner]=useState('all'),[warningOnly,setWarningOnly]=useState(false),[sourceOpen,setSourceOpen]=useState(false);
 const [navigationRevision,setNavigationRevision]=useState(0);
 const [libraryVideoId,setLibraryVideoId]=useState('');
 const [scoreTarget,setScoreTarget]=useState<any>(null),[scorePlaylist,setScorePlaylist]=useState<string[]>([]);
 const navigate=(p:string)=>{setNavigationRevision(v=>v+1);setPage(p);setError('');window.scrollTo(0,0)};
 const refresh=async()=>setLibrary(await api('/matches'));
 async function work(fn:()=>Promise<void>){setBusy(true);setError('');try{await fn()}catch(e){setError('操作未完成，请检查文件或重试。已有比赛不会被重置。');setErrorDetail(String(e))}finally{setBusy(false)}}
  useEffect(()=>{(async()=>{try{const [s,h,l,a,g]=await Promise.all([api('/settings'),api('/health'),api('/matches'),api('/preview/workspace'),api('/player-groups')]);setSettings(s);setVersions(h);setPage(h.video_first&&s.start_page==='home'?'home':h.start_page||'home');setLibrary(l);setAthletes(a.athletes);setPlayerGroups(g);setProMatches(a.matches);setOnboarding(!s.onboarding_complete&&!h.video_first);}catch(e){setError('本地数据无法读取。请关闭应用后重试，或查看启动日志。');setErrorDetail(String(e))}finally{setReady(true)}})()},[]);
 useEffect(()=>{document.documentElement.dataset.theme=settings.theme==='light'?'light':'dark'},[settings.theme]);
 useEffect(()=>{document.title=versions.product_name?`${versions.product_name} v${versions.version||''} Preview`:'PTTI · Dark Studio'},[versions.product_name,versions.version]);
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4500);return()=>clearTimeout(timer)},[toast]);
 async function preferences(change:Partial<Settings>){const value={...settings,...change};await work(async()=>{const saved=await api('/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(value)});setSettings(saved);setToast('设置已保存')})}
  async function finishOnboarding(action:string){await work(async()=>{const s=await api('/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...settings,onboarding_complete:true})});setSettings(s);setOnboarding(false);if(action==='sample')await sample();else if(action==='start')navigate(versions.start_page||'home')})}
 async function sample(){const result=await api('/matches/sample',{method:'POST'});setMatch(result.match);setSection('overview');navigate('dashboard');await refresh()}
  async function open(id:string){await work(async()=>{setMatch(await api('/matches/'+id));setSection('overview');setGame('all');setServer('all');setWinner('all');setPointSearch('');setWarningOnly(false);navigate('dashboard')})}
  async function showAthlete(id:string){await work(async()=>{setSelectedAthlete(await api('/players/'+encodeURIComponent(id)));navigate('playerDetail')})}
  async function saveProMatch(){await work(async()=>{const body={...proDraft,player_a_id:proDraft.player_a_id||athletes[0]?.athlete_id,player_b_id:proDraft.player_b_id||athletes[1]?.athlete_id};if(proVideo){const data=new FormData();data.append('metadata',JSON.stringify(body));data.append('video_source_note',proVideoSourceNote);data.append('rights_confirmed',String(proRightsConfirmed));data.append('file',proVideo);await api('/professional-matches/local-video',{method:'POST',body:data})}else{body.video_source_type=proDraft.external_reference_url?'REFERENCE_ONLY':'NO_VIDEO';body.rights_status=proDraft.external_reference_url?'REFERENCE_ONLY':'NO_VIDEO';await api('/professional-matches',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})}setProDraft({event_name:'',player_a_id:'',player_b_id:'',round:'',external_reference_url:''});setProVideo(null);setProRightsConfirmed(false);setProVideoSourceNote('');const p=await api('/professional-matches');setProMatches(p);setToast(proVideo?'比赛与授权视频已登记；尚未启动分析':'职业比赛记录已保存')})}
 async function upload(save:boolean){if(!file)return;const data=new FormData();data.append('file',file);data.append('metadata',JSON.stringify(meta));data.append('preview',String(!save));await work(async()=>{const result=await api('/matches/import',{method:'POST',body:data});setPreview(result);setStep(3);if(save&&result.match){setMatch(result.match);setSection('overview');await refresh();navigate('dashboard');setFile(null);setMeta(initialMeta);setStep(1);setPreview(null);setToast('比赛已保存到本机')}})}
 const name=(p:string)=>match?.metadata[p==='A'?'player_a':'player_b']||p;
 function Metric({p,k}:{p:string;k:string}){const m=match!.analysis.players[p][k];return <Card className="metric"><div className="metric-label">{metricNames[k]} <span tabIndex={0} className="help" title={metricHelp[k]} aria-label={metricHelp[k]}>ⓘ</span></div><strong>{m.value==null?'—':m.value+(k==='average_rally'?' 次':'%')}</strong><div className="denominator">{m.numerator!==undefined?`${m.numerator} / ${m.denominator}`:`有效样本 ${m.denominator}`} {k==='average_rally'?'分':'有效样本'}</div><Evidence state={m.evidence_state}/><details><summary>样本说明</summary><p>{metricHelp[k]}</p><p>排除 {m.excluded_rows??0} · 未知 {m.unknown??0} · 无法判断 {m.unclear??0} · 不适用 {m.not_applicable??0} · 机会未确认 {m.unresolved_eligibility??0}</p></details></Card>}
 function MatchCards({items}:{items:any[]}){return <div className="library-grid">{items.map(m=><Card key={m.id}><div className="card-top"><span className="badge">{m.metadata.synthetic?'合成示例':'比赛记录'}</span>{page==='library'&&<button className="icon-button" aria-label={'删除 '+m.metadata.name} onClick={()=>setDeleteTarget(m)}>删除</button>}</div><h2>{m.metadata.name}</h2><p>{m.metadata.player_a} vs {m.metadata.player_b}</p><p>{m.metadata.date||'日期未填写'} · {m.metadata.event||'赛事未填写'}</p><div className="card-meta">{m.point_count} 分 · {schemaName(m.source_schema)}</div><p className="small">{m.warning_count?`${m.warning_count} 条数据警告，请查看证据状态`:'数据已检查；指标按各自证据显示'}</p><button className="primary" onClick={()=>open(m.id)}>查看分析 →</button></Card>)}</div>}
 const warningRows=new Set(match?.validation.issues.filter(i=>i.row&&i.level==='warning').map(i=>(i.row||0)-2)||[]);
 const pointRows=(match?.points||[]).map((r,index)=>({r,index})).filter(({r,index})=>(game==='all'||r.game===game)&&(server==='all'||r.server===server)&&(winner==='all'||r.winner===winner)&&(!pointSearch||Object.values(r).join(' ').toLowerCase().includes(pointSearch.toLowerCase())||Object.values(r).some(v=>display(v).includes(pointSearch)))&&(!warningOnly||warningRows.has(index)||Object.values(r).some(v=>['unknown','unclear','not_applicable'].includes(v))));
 const pointFields=['game','point','server','winner','score','serve_placement','serve_type','receive_type','third_ball_attack','rally_length','notes'];
 const filteredLibrary=library.filter(m=>(!search||[m.metadata.name,m.metadata.player_a,m.metadata.player_b].join(' ').includes(search))&&(!date||m.metadata.date===date));
  const visibleAthletes=athletes.filter(a=>(!playerGroupFilter||a.groups.includes(playerGroupFilter))&&(!playerSearch||[a.canonical_name_en,a.canonical_name_zh,a.country_or_association].join(' ').toLowerCase().includes(playerSearch.toLowerCase())));
  const groupName=(code:string)=>playerGroups.find(g=>g.group_code===code)?.display_name||code;
  function AthleteCards({items}:{items:any[]}){return <div className="library-grid athlete-grid">{items.map(a=><Card key={a.athlete_id} className="athlete-card"><div className="card-top"><span className="badge">{a.groups.includes('LEGACY_CHAMPION_REFERENCE')?'历史冠军参考':'职业运动员'}</span><span className="rank-pill">{a.current_world_rank?`WR #${a.current_world_rank}`:'—'}</span></div><h2>{a.canonical_name_zh||a.canonical_name_en}</h2><p>{a.canonical_name_en}</p><p>{countryName(a.country_or_association)}{a.current_world_rank?' · '+a.ranking_points?.toLocaleString()+' 分':''}</p><button className="primary" onClick={()=>showAthlete(a.athlete_id)}>查看运动员资料 →</button></Card>)}</div>}
  function ProfessionalMatchCards({items}:{items:any[]}){
    const stages:Record<string,string>={NOT_ANALYZED:'尚未分析',VIDEO_READY:'本机视频已登记',VIDEO_VALIDATED:'视频已检查',POINT_SEGMENTATION_PENDING:'待分局分',POINTS_DETECTED:'逐分已检测',BALLTRACK_COMPLETE:'球追踪已完成',TACTICAL_ANALYSIS_PENDING:'待战术分析',COMPLETE:'已完成',FAILED:'处理失败'};
    const clipStages:Record<string,string>={queued:'等待处理',running:'处理中',complete:'短片球追踪已完成',failed:'短片处理失败'};
    return items.length?<div className="library-grid">{items.map(m=>{
      const clip=m.video_analysis;
      const hasLocalVideo=['LOCAL_USER_VIDEO','LICENSED_WTT_LOCAL','RESEARCH_DATASET'].includes(m.video_source_type);
      return <Card key={m.match_id} className="pro-match-card">
        <div className="card-top"><span className="badge">{competitionName(m.competition_level)}</span><span className="badge quiet-badge">{stages[m.analysis_status]||'状态待核实'}</span></div>
        <h2>{m.event_name}</h2>
        <p>{m.players?.player_a?.canonical_name_zh||m.players?.player_a?.canonical_name_en} vs {m.players?.player_b?.canonical_name_zh||m.players?.player_b?.canonical_name_en}</p>
        <p>{roundName(m.round)} · {m.event_date||'日期未核实'}</p>
        <p>{m.final_score?`比赛局分 ${m.final_score.player_a_games} : ${m.final_score.player_b_games}`:'比分未记录'} · {m.video_source_type==='REFERENCE_ONLY'?'仅有外部赛事参考':hasLocalVideo?'本机授权视频':'无视频'}</p>
        {m.video_metadata&&<p className="small">{m.video_original_filename} · {m.video_metadata.duration?.toFixed(1)} 秒 · {m.video_metadata.width}×{m.video_metadata.height} · {Math.round(m.video_metadata.fps)} fps · {m.video_metadata.codec} · 旋转 {m.video_metadata.orientation_degrees??"未知"}° · 音轨 {m.video_metadata.audio_streams?.length??0} · 输入级别 {m.video_metadata.quality.level}</p>}
        {m.video_source_note&&<details><summary>视频来源与授权说明</summary><p>{m.video_source_note}</p><small>SHA-256：{m.video_metadata?.sha256}</small></details>}
        {hasLocalVideo&&<p className="small">全场分析按 60 秒可恢复分块运行；每段结果映射回整场时间轴。镜头与逐分结构仍需人工确认。</p>}
        {clip&&<div className="clip-analysis-state"><p><strong>短片球追踪：{clipStages[clip.status]||'状态待核实'}</strong></p><p className="small">范围：单段短片 · {clip.clip_filename||'视频片段'}{clip.video?.duration?` · ${clip.video.duration.toFixed(1)} 秒`:''}</p>{clip.status==='failed'&&clip.error&&<p className="small" role="alert">{clip.error}</p>}{clip.source_note&&<details><summary>短片来源与授权说明</summary><p>{clip.source_note}</p><small>SHA-256：{clip.clip_sha256}</small></details>}{clip.analysis_id&&<button onClick={()=>navigate('vision')}>在视频分析页查看结果</button>}</div>}
        {m.external_reference_url&&<a href={m.external_reference_url} target="_blank" rel="noreferrer">查看来源记录 ↗</a>}
        {hasLocalVideo&&<button onClick={()=>{setTimelineMatchId(m.match_id);navigate('timeline')}}>打开比赛时间轴</button>}
        {m.full_match_analysis&&<p className="small">全场处理：{m.full_match_analysis.stage} · {m.full_match_analysis.completed_chunks||0}/{m.full_match_analysis.total_chunks||0} 分块</p>}
      </Card>
    })}</div>:<Empty title="暂无职业比赛记录" text="可登记比赛资料，也可选择你有权在本机分析的视频。PTTI 不会下载外部视频。"/>;
  }
 function NewProfessionalMatch(){return <Card><h2>新建职业比赛记录</h2><p>可只保存比赛资料，也可登记你有权在本机分析的视频。外部参考链接只作来源记录，不会抓取或下载内容。</p><div className="form-grid"><label>赛事名称<input required maxLength={300} value={proDraft.event_name} onChange={e=>setProDraft({...proDraft,event_name:e.target.value})}/></label><label>比赛日期<input type="date" value={proDraft.event_date||''} onChange={e=>setProDraft({...proDraft,event_date:e.target.value||null})}/></label><label>球员 A<select required value={proDraft.player_a_id} onChange={e=>setProDraft({...proDraft,player_a_id:e.target.value})}><option value="">请选择</option>{athletes.map(a=><option key={a.athlete_id} value={a.athlete_id}>{a.canonical_name_zh||a.canonical_name_en} · {a.canonical_name_en}</option>)}</select></label><label>球员 B<select required value={proDraft.player_b_id} onChange={e=>setProDraft({...proDraft,player_b_id:e.target.value})}><option value="">请选择</option>{athletes.map(a=><option key={a.athlete_id} value={a.athlete_id}>{a.canonical_name_zh||a.canonical_name_en} · {a.canonical_name_en}</option>)}</select></label><label>轮次<input maxLength={150} value={proDraft.round} onChange={e=>setProDraft({...proDraft,round:e.target.value})}/></label><label>官方赛事参考链接（可选）<input type="url" value={proDraft.external_reference_url} onChange={e=>setProDraft({...proDraft,external_reference_url:e.target.value})}/></label><label className="wide">本机视频（MP4、MOV、MKV、AVI，可选）<input type="file" accept="video/mp4,video/quicktime,video/x-matroska,video/x-msvideo,.mp4,.mov,.mkv,.avi" onChange={e=>{setProVideo(e.target.files?.[0]||null);setProRightsConfirmed(false)}}/></label><label className="wide">视频来源 / 授权说明<input maxLength={500} value={proVideoSourceNote} onChange={e=>setProVideoSourceNote(e.target.value)} placeholder="例如：本人拍摄；或填写授权方和许可范围"/></label></div>{proVideo&&<><label className="check"><input type="checkbox" checked={proRightsConfirmed} onChange={e=>setProRightsConfirmed(e.target.checked)}/> 我确认有权将此视频用于本机分析</label><p className="small">PTTI 会复制到本机数据目录的 professional-videos 文件夹；原文件不会移动或改写，也不会上传云端。系统会读取媒体轨道、时长、画质与方向信息，并记录文件哈希。</p><p className="warning-note">登记完整比赛不会自动分析。全场 BallTrack 按 60 秒可恢复分块运行，设备与处理时长会影响整体耗时。</p></>}<p className="small">外部链接只建立参考记录；没有视频时也可保存比赛基本资料。</p><button className="primary" disabled={busy||!proDraft.event_name||!proDraft.player_a_id||!proDraft.player_b_id||proDraft.player_a_id===proDraft.player_b_id||(!!proVideo&&(!proRightsConfirmed||!proVideoSourceNote.trim()))} onClick={saveProMatch}>{proVideo?'登记比赛与本机视频':'保存职业比赛记录'}</button></Card>}
 function Points(){return <><div className="filter-bar"><label>搜索<input aria-label="搜索逐分记录" value={pointSearch} placeholder="球名、备注、未知…" onChange={e=>setPointSearch(e.target.value)}/></label>{[['game','局',game,setGame],['server','发球方',server,setServer],['winner','得分方',winner,setWinner]].map(([key,label,value,setter]:any)=><label key={key}>{label}<select value={value} onChange={e=>setter(e.target.value)}><option value="all">全部</option>{key==='game'?[...new Set(match!.points.map(r=>r.game))].map(g=><option key={g} value={g}>第 {g} 局</option>):['A','B'].map(p=><option key={p} value={p}>{name(p)}</option>)}</select></label>)}<label className="check"><input type="checkbox" checked={warningOnly} onChange={e=>setWarningOnly(e.target.checked)}/> 仅看警告或不确定记录</label></div><p className="small">筛选结果 {pointRows.length} / {match!.points.length} 分。回合长度包含发球；不确定标签不会变成数值。</p><Card><div className="table-wrap"><table><thead><tr>{pointFields.map(f=><th key={f}>{f==='score'?'本分结束后比分':f==='notes'?'证据备注':fieldNames[f]}</th>)}</tr></thead><tbody>{pointRows.map(({r,index})=><tr key={index}>{pointFields.map(f=><td key={f}>{f==='score'?r.score_a+' : '+r.score_b:f==='server'||f==='winner'?name(r[f]):f==='notes'?r.source_notes||r.notes||'—':display(r[f])}</td>)}</tr>)}</tbody></table>{!pointRows.length&&<p>没有符合条件的记录，请调整筛选。</p>}</div><button onClick={()=>setSourceOpen(!sourceOpen)}>{sourceOpen?'收起':'展开'}原始研究字段</button>{sourceOpen&&<div className="table-wrap"><table><thead><tr>{Object.keys(match!.points[0]||{}).filter(f=>f.startsWith('source_')).map(f=><th key={f}>{fieldNames[f.slice(7)]||f.slice(7)}<small>{f}</small></th>)}</tr></thead><tbody>{pointRows.map(({r,index})=><tr key={index}>{Object.keys(match!.points[0]||{}).filter(f=>f.startsWith('source_')).map(f=><td key={f}>{r[f]||'—'}</td>)}</tr>)}</tbody></table>{!Object.keys(match!.points[0]||{}).some(f=>f.startsWith('source_'))&&<p>标准格式原值保存在导出 JSON 的来源记录中。</p>}</div>}</Card></>}
 return <StudioShell page={page} navigate={navigate} query={feedQuery} onQueryChange={value=>{setFeedQuery(value);if(!['home','players','professionalMatches'].includes(page))navigate('home')}} searchEnabled={Boolean(versions.video_feed)} buildLabel={previewBuildLabel(versions)}>
 {error&&<div role="alert" className="error-banner"><strong>{error}</strong><p>重新选择文件或关闭后重开；仍有问题请截图反馈。</p><button onClick={()=>{setError('');setErrorDetail('')}}>关闭提示</button><details><summary>技术详情</summary><pre>{errorDetail}</pre></details></div>}{busy&&<div role="status" className="loading">正在处理，请稍候…</div>}{toast&&<div role="status" className="toast">✓ {toast}</div>}
 {!ready?<Empty title="正在打开比赛工作台" text="正在读取本地数据，请稍候。"/>:<>
  {versions.video_feed&&['home','players','professionalMatches','feedHistory','feedFavorites'].includes(page)&&<VideoFeed page={page} revision={navigationRevision} query={feedQuery} onPlay={id=>{setLibraryVideoId(id);setScoreTarget(null);navigate('videoEvidence')}} onTools={()=>navigate('libraryTools')} navigate={navigate}/>}
  {versions.video_first&&(!versions.video_feed||page==='libraryTools')&&['home','players','professionalMatches','libraryTools'].includes(page)&&<MatchVideoLibrary page={page} revision={navigationRevision} navigate={navigate} onOpenVideo={id=>{setLibraryVideoId(id);setScoreTarget(null);navigate('videoEvidence')}} onOpenScore={row=>{setLibraryVideoId(row.video_id);setScoreTarget(row);setScorePlaylist([]);navigate('videoEvidence')}} onScorePlaylist={async ids=>{try{const r=await api('/video-evidence/scores/playlist',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(ids)});setLibraryVideoId('');setScoreTarget(null);setScorePlaylist(r.evidence_ids);navigate('videoEvidence')}catch(e:any){setError(String(e))}}}/>}
 {(!versions.video_first||!['home','players','professionalMatches'].includes(page))&&['home','players','professionalMatches','videoCenter','research'].includes(page)&&<ProfessionalWorkspace page={page} navigationRevision={navigationRevision} navigate={navigate} onTimeline={id=>{setTimelineMatchId(id);navigate('timeline')}}/>}
  {page==='demo'&&<><PageHeader title="Developer / Demo" text="合成示例与工程工具独立存放，不构成职业比赛分析数据。"/><Card><h2>本地逐分工作区</h2><div className="actions"><button onClick={()=>navigate('import')}>导入逐分 CSV</button><button onClick={()=>navigate('library')}>本地比赛库</button><button onClick={()=>work(sample)}>加载合成示例</button><button onClick={()=>navigate('vision')}>视觉工程工具</button><button onClick={()=>navigate('wttInbox')}>WTT 授权收件目录</button></div><p>所有示例会保留合成数据标记。</p></Card></>}
  {page==='wttInbox'&&<WTTInbox athletes={athletes} onImported={()=>api('/professional-matches').then(setProMatches)}/>}
  {page==='timeline'&&timelineMatchId&&<FullMatchTimeline matchId={timelineMatchId} onBack={()=>navigate('professionalMatches')}/>}
  {page==='videoEvidence'&&<VideoEvidencePlayer initialVideoId={libraryVideoId} initialScoreTarget={scoreTarget} initialScorePlaylist={scorePlaylist} onInitialScoreHandled={()=>setScoreTarget(null)} onInitialPlaylistHandled={()=>setScorePlaylist([])} videoFirst={Boolean(versions.video_first)} watchMode={Boolean(versions.video_first)}/>}
 {page==='dashboard'&&!match&&<><PageHeader title="比赛分析"/><Empty title="先选择一场比赛" text="导入 CSV 或打开比赛库，即可查看分析。"><button className="primary" onClick={()=>navigate('import')}>导入比赛</button><button onClick={()=>navigate('library')}>打开比赛库</button></Empty></>}
 {page==='dashboard'&&match&&<><PageHeader title={match.metadata.name} text={`${name('A')} vs ${name('B')} · ${match.metadata.date||'日期未填写'} · ${match.metadata.event||'比赛'} · ${match.points.length} 分`}><details className="export-menu"><summary className="button primary">导出分析 ▾</summary><div><a href={'/api/matches/'+match.id+'/export'} download>导出 JSON</a><a href={'/api/matches/'+match.id+'/report'} download>导出 HTML 报告</a><button onClick={()=>window.print()}>打印 / 保存 PDF（实验功能）</button></div></details></PageHeader><div className="match-status"><span className="badge">{match.metadata.synthetic?'合成示例 · 非真实比赛':'比赛记录'}</span><span>{schemaName(match.provenance?.source_schema)}</span><span>警告 {match.validation.issues.filter(i=>i.level==='warning').length} 条</span><span>已自动保存</span></div><div className="tabs" role="navigation" aria-label="分析分区">{[['overview','总览'],['service','发接发'],['third','第三板'],['rally','回合'],['points','逐分'],['evidence','证据']].map(([s,l])=><button key={s} className={section===s?'active':''} onClick={()=>{setSection(s);window.scrollTo(0,0)}}>{l}</button>)}</div>{!match.analysis.evidence&&<p className="warning-note">旧版分析原值已保留。重新导入 CSV 可使用新版证据展示，不会自动改变旧结果。</p>}{['overview','service','third','rally'].includes(section)&&<div className="players">{['A','B'].map(p=><div key={p}><h2 className={'player-name player-'+p}>{name(p)}</h2><div className="metric-grid">{(section==='overview'?Object.keys(metricNames):section==='service'?['serve_win','receive_win']:section==='third'?['third_ball_attack','third_ball_win']:['average_rally']).map(k=><Metric key={k} p={p} k={k}/>)}</div></div>)}</div>}{section==='overview'&&<><Card><h2>比分走势</h2><p className="small">每分结束后的比分；新一局从零开始。</p><Suspense fallback={<p>正在绘制比分走势…</p>}><ScoreChart points={match.analysis.progression} names={[name('A'),name('B')]}/></Suspense></Card><Card><h2>连续得分 / 比赛节奏</h2><div className="runs">{match.analysis.runs.map((r:any,i:number)=><button key={i} onClick={()=>{setSection('points');setGame(r.game);setWinner(r.player)}}>第 {r.game} 局 · {name(r.player)} 连得 {r.length} 分</button>)}</div></Card></>}{section==='service'&&<div className="players">{['A','B'].map(p=><Card key={p}><h2>{name(p)} · 发接发战术数据</h2>{[['by_serve_placement','发球落点'],['by_serve_type','发球旋转'],['by_receive_type','接发方式']].map(([k,l])=><section key={k}><h3>{l}</h3>{Object.keys(match.analysis.players[p][k]).length?<table><thead><tr><th>类别</th><th>得分率</th><th>有效样本</th></tr></thead><tbody>{Object.entries(match.analysis.players[p][k]).map(([v,m]:any)=><tr key={v}><td>{display(v)}</td><td>{m.value==null?<Evidence state={m.evidence_state}/>:m.value+'%'}</td><td>{m.numerator} / {m.denominator}</td></tr>)}</tbody></table>:<p>当前数据不足以生成可靠的战术分析。PTTI 不会根据比分猜测战术字段。</p>}</section>)}</Card>)}</div>}{section==='third'&&<Card><h2>第三板证据说明</h2><p>抢攻率只使用已确认“是 / 否”的发球机会；抢攻得分率只使用已确认抢攻的分。未知机会不会进入已确认分母。</p><p>抢攻后赢下该分不等于第三板直接得分。战术有效样本少于 5，或未确认数据超过 30%，不会显示比例；这只是产品显示门槛。</p></Card>}{section==='rally'&&<Card><h2>回合长度分布</h2>{Object.entries(match.analysis.players.A.rally_bands).map(([k,m]:any)=><div className="band" key={k}><span>{k==='short'?'短回合 · 1–4 次':k==='medium'?'中回合 · 5–8 次':'长回合 · 9 次以上'}</span>{m.value==null?<Evidence state={m.evidence_state}/>:<><meter min="0" max="100" value={m.value}/><strong>{m.value}%</strong><small>{m.numerator} / {m.denominator}</small></>}</div>)}</Card>}{section==='points'&&Points()}{section==='evidence'&&<><Provenance match={match}/><h2>数据检查</h2><Issues items={match.validation.issues}/></>}<p className="privacy-note">仅描述已记录样本。未知 ≠ 零；事实 ≠ 科学研究结论。</p></>}
 {page==='library'&&<><PageHeader title="比赛库" text={`${library.length} 场比赛保存在本机。`}><button className="primary" onClick={()=>navigate('import')}>新建比赛</button></PageHeader><div className="filter-bar"><label>搜索比赛或球员<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="比赛名称、球员姓名"/></label><label>比赛日期<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label><button onClick={()=>{setDate('');setSearch('')}}>清除筛选</button></div>{filteredLibrary.length?<MatchCards items={filteredLibrary}/>:<Empty title={library.length?'没有符合条件的比赛':'还没有保存的比赛'} text={library.length?'调整搜索条件或清除筛选。':'导入一场比赛，PTTI 会自动检查并生成分析。'}/>}</>}
 {page==='settings'&&<><PageHeader title="设置" text="简单、只在本机生效。"/><Card className="settings-grid"><label>界面语言<select value="zh-CN" disabled><option value="zh-CN">中文</option></select></label><label>外观<select value={settings.theme} disabled={busy} onChange={e=>preferences({theme:e.target.value as Settings['theme']})}><option value="system">Dark Studio（默认）</option><option value="light">浅色</option><option value="dark">深色</option></select></label><label>打开应用时<select value="home" disabled><option value="home">显示职业首页</option></select></label><div><h3>首次使用说明</h3><button onClick={()=>setOnboarding(true)}>重新查看使用说明</button></div></Card><Card><h2>本地数据</h2><p>Preview 数据保存在独立 PTTI-Dev 开发目录。正式 v0.1.2 数据库不参与此 Preview。</p><button onClick={()=>work(async()=>{const bridge=(window as any).pywebview?.api;if(!bridge)throw new Error('仅桌面版支持打开数据文件夹');await bridge.open_data_folder();setToast('已打开本地数据文件夹')})}>打开数据文件夹</button><p>无需账号、无遥测、无静默上传、无外部 AI 调用。</p></Card><Card><h2>版本信息</h2><p>应用 {versions.score_navigation_preview?previewBuildLabel(versions):versions.version} · 数据格式 {versions.schema_version}</p><p>分析规则 {versions.analytics_version} · 历史适配器 {versions.adapter_version}</p></Card></>}
 {page==='about'&&<><DesktopUpdates versions={versions}/><PageHeader title="关于 PTTI" text="Personal Table Tennis Intelligence · 个人乒乓球比赛智能分析系统"/><Card><h2>让比赛记录成为可检查的证据。</h2><p>为你与凯凯的比赛分析而开发。目前完整开放比赛分析；视频球追踪为实验模块，其他模块仍为规划。</p><p>{(versions.score_navigation_preview||versions.dual_source_preview)?previewBuildLabel(versions):'v0.2 Professional Preview'} · 独立开发预览。保留 Protocol v0.3 兼容与研究原值。</p><p>本地优先：无需账号、无需联网分析，不上传比赛，不调用外部模型。</p><p>研究依据：sports-ai-lab。Pilot 1C 保持 REVISE / HOLD；Pilot 2 尚未开始。未宣称科学验证的 AI 或战术能力。</p><p>凯凯首次独立测试：待完成。操作困惑也属于需要修复的问题。</p><a href="https://github.com/wang14759761129-tech/sports-ai-lab" target="_blank" rel="noreferrer">GitHub · 公开源代码与研究依据 ↗</a><p>Evidence-aware intelligence · 不知道的，不猜。</p></Card></>}
 {page==='vision'&&<Vision onCinema={()=>navigate('home')}/>}
 {planned[page]&&<><PageHeader title={planned[page]}/><Empty title="规划中 · 尚未开放" text={plannedText[page]}><p>目前比赛分析开放，视频球追踪为实验模块，不生成模拟结论。</p><button className="primary" onClick={()=>navigate('home')}>返回首页</button></Empty></>}
 </>}
 {onboarding&&ready&&<Modal title="欢迎使用 PTTI" onClose={()=>finishOnboarding('later')}><p>三步开始，不需要账号或开发工具。</p><ol className="onboarding">{versions.video_first?<><li><strong>浏览比赛视频</strong><span>选择项目与比赛，通过允许的来源观看。</span></li><li><strong>确认并观看</strong><span>核对比赛关联，直接播放完整录像，无需运行模型。</span></li><li><strong>保存关键球</strong><span>标记片段、写笔记，保存到专题反复复盘。</span></li></>:versions.start_page==='videoEvidence'?<><li><strong>导入本地录像</strong><span>引用原文件，直接播放，无需启动 AI。</span></li><li><strong>留下关键片段</strong><span>标记起止点、标签和笔记。</span></li><li><strong>连续复盘</strong><span>收藏同类关键球，下次从证据开始。</span></li></>:<><li><strong>导入完整比赛</strong><span>选择你有权使用的完整比赛录像。</span></li><li><strong>查看球轨迹</strong><span>视频属性与分析任务进度清晰可见。</span></li><li><strong>确认比赛时间轴</strong><span>审核回合建议、编辑逐分边界；不知道的，不猜。</span></li></>}</ol><div className="actions"><button className="primary" disabled={busy} onClick={()=>finishOnboarding('start')}>开始使用</button><button disabled={busy} onClick={()=>finishOnboarding('later')}>以后再说</button></div></Modal>}
 {deleteTarget&&<Modal title="确定删除这场比赛？" onClose={()=>setDeleteTarget(null)}><p>该操作将删除本机保存的“{deleteTarget.metadata.name}”比赛数据，无法撤销。</p><div className="actions"><button autoFocus disabled={busy} onClick={()=>setDeleteTarget(null)}>取消</button><button className="danger" disabled={busy} onClick={()=>work(async()=>{await api('/matches/'+deleteTarget.id,{method:'DELETE'});if(match?.id===deleteTarget.id)setMatch(null);setDeleteTarget(null);await refresh();setToast('比赛已删除')})}>删除</button></div></Modal>}
 </StudioShell>
}
createRoot(document.getElementById('root')!).render(<App/>);
